import React, { useState, useEffect } from "react";

const initialExpenses = [
  {
    id: 1,
    date: "2023-05-10",
    category: "arriendo",
    amount: 1200000,
    paymentMethod: "transferencia",
    description: "Arriendo oficina central",
    receipt: null,
  },
  {
    id: 2,
    date: "2023-05-05",
    category: "servicios",
    amount: 150000,
    paymentMethod: "tarjeta",
    description: "Pago de servicios básicos",
    receipt: null,
  },
  // ...agrega más ejemplos si quieres
];

function ExpensesPage() {
  const [expenses, setExpenses] = useState(() => {
    const stored = localStorage.getItem("expenses");
    return stored ? JSON.parse(stored) : initialExpenses;
  });
  const [form, setForm] = useState({
    date: "",
    category: "",
    amount: "",
    paymentMethod: "",
    description: "",
    receipt: null,
  });

  // Guardar en localStorage cada vez que cambian los gastos
  useEffect(() => {
    localStorage.setItem("expenses", JSON.stringify(expenses));
  }, [expenses]);

  // Manejar cambios en el formulario
  const handleChange = (e) => {
    const { name, value, files } = e.target;
    if (name === "receipt") {
      setForm({ ...form, receipt: files[0] });
    } else {
      setForm({ ...form, [name]: value });
    }
  };

  // Manejar envío del formulario
  const handleSubmit = (e) => {
    e.preventDefault();
    setExpenses([
      ...expenses,
      {
        ...form,
        id: expenses.length ? Math.max(...expenses.map((e) => e.id)) + 1 : 1,
      },
    ]);
    setForm({
      date: "",
      category: "",
      amount: "",
      paymentMethod: "",
      description: "",
      receipt: null,
    });
  };

  return (
    <div className="container mx-auto px-4 py-6">
      <h1 className="text-2xl font-bold mb-4">Gastos</h1>
      {/* Formulario de registro rápido */}
      <form
        className="bg-white rounded-lg shadow-md p-6 mb-6"
        onSubmit={handleSubmit}
      >
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <input
            type="date"
            name="date"
            value={form.date}
            onChange={handleChange}
            className="border rounded px-3 py-2"
            required
          />
          <select
            name="category"
            value={form.category}
            onChange={handleChange}
            className="border rounded px-3 py-2"
            required
          >
            <option value="">Categoría</option>
            <option value="arriendo">Arriendo</option>
            <option value="servicios">Servicios</option>
            <option value="insumos">Insumos</option>
            <option value="sueldos">Sueldos</option>
            <option value="imprevistos">Imprevistos</option>
          </select>
          <input
            type="number"
            name="amount"
            value={form.amount}
            onChange={handleChange}
            className="border rounded px-3 py-2"
            placeholder="Monto"
            required
          />
          <select
            name="paymentMethod"
            value={form.paymentMethod}
            onChange={handleChange}
            className="border rounded px-3 py-2"
            required
          >
            <option value="">Método de pago</option>
            <option value="efectivo">Efectivo</option>
            <option value="transferencia">Transferencia</option>
            <option value="tarjeta">Tarjeta</option>
          </select>
          <input
            type="text"
            name="description"
            value={form.description}
            onChange={handleChange}
            className="border rounded px-3 py-2"
            placeholder="Descripción"
          />
          <input
            type="file"
            name="receipt"
            onChange={handleChange}
            className="border rounded px-3 py-2"
            accept="image/*,.pdf"
          />
        </div>
        <button
          type="submit"
          className="mt-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-2 px-4 rounded"
        >
          Registrar Gasto
        </button>
      </form>

      {/* Tabla de gastos */}
      <div className="bg-white rounded-lg shadow-md p-6">
        <h2 className="text-xl font-bold mb-4">Listado de Gastos</h2>
        <table className="min-w-full divide-y divide-gray-200">
          <thead>
            <tr>
              <th className="px-4 py-2">Fecha</th>
              <th className="px-4 py-2">Categoría</th>
              <th className="px-4 py-2">Monto</th>
              <th className="px-4 py-2">Método</th>
              <th className="px-4 py-2">Descripción</th>
            </tr>
          </thead>
          <tbody>
            {expenses.map((g) => (
              <tr key={g.id}>
                <td className="px-4 py-2">{g.date}</td>
                <td className="px-4 py-2 capitalize">{g.category}</td>
                <td className="px-4 py-2">${Number(g.amount).toLocaleString()}</td>
                <td className="px-4 py-2 capitalize">{g.paymentMethod}</td>
                <td className="px-4 py-2">{g.description}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default ExpensesPage;
